import { createRootRoute, createRoute, redirect } from "@tanstack/react-router";
import { ArtifactsRoute } from "./routes/artifacts";
import { ArtifactsIndexRoute } from "./routes/artifacts-index";
import { ArtifactDetailRoute } from "./routes/artifact.$componentId";
import { ArtifactSettingsRoute } from "./routes/artifact-settings";
import { BuildsIndexRoute } from "./routes/builds-index";
import { JobDetailRoute } from "./routes/builds.$jobId";
import { BuildDetailRoute } from "./routes/builds.$jobId.builds.$buildId";
import { BuildsRoute } from "./routes/builds";
import { CacheRoute } from "./routes/cache";
import { CredentialsRoute } from "./routes/credentials";
import { DashboardRoute } from "./routes/dashboard";
import { LoginRoute } from "./routes/login";
import { PipelineDetailRoute } from "./routes/pipeline.$pipelineId";
import { PipelinesRoute } from "./routes/pipelines";
import { ProjectBranchesRoute } from "./routes/project.$projectName.branches";
import { ProjectDetailRoute } from "./routes/project.$projectName";
import { ProjectTagsRoute } from "./routes/project.$projectName.tags";
import { ProjectsRoute } from "./routes/projects";
import { RootRoute } from "./routes/root";
import { SecretDetailRoute } from "./routes/secret.$secretId";
import { SecretsRoute } from "./routes/secrets";
import { SettingsRoute } from "./routes/settings";
import { WorkersRoute } from "./routes/workers";
import { WorkersOverviewRoute } from "./routes/workers-overview";
import { WorkersProjectsRoute } from "./routes/workers-projects";
import { WorkersProjectDetailRoute } from "./routes/workers-projects.$projectName";
import { WorkersPodsRoute } from "./routes/workers-pods";
import { WorkersPodDetailRoute } from "./routes/workers-pods.$podName";
import { WorkersDeploymentsRoute } from "./routes/workers-deployments";
import { WorkersDeploymentDetailRoute } from "./routes/workers-deployments.$deploymentName";
import { WorkersBuildsRoute } from "./routes/workers-builds";
import { WorkersBuildDetailRoute } from "./routes/workers-builds.$buildName";
import { WorkersRoutesRoute } from "./routes/workers-routes";
import { WorkersRouteDetailRoute } from "./routes/workers-routes.$routeName";
import { WorkersServicesRoute } from "./routes/workers-services";
import { WorkersServiceDetailRoute } from "./routes/workers-services.$serviceName";
import { WorkersPVCsRoute } from "./routes/workers-persistentvolumeclaims";
import { WorkersPVCDetailRoute } from "./routes/workers-persistentvolumeclaims.$claimName";
import { ReleasesRoute } from "./routes/releases";
import { ReleasesIndexRoute } from "./routes/releases-index";
import { ReleasesCalendarRoute } from "./routes/releases-calendar";
import { ReleasesArtifactsRoute } from "./routes/releases-artifacts";
import { ReleaseDetailRoute } from "./routes/releases.$releaseName";


const rootRoute = createRootRoute({
  component: RootRoute,
});

const loginRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/login",
  component: LoginRoute,
});

const dashboardRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/",
  component: DashboardRoute,
});

const projectsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/projects",
  component: ProjectsRoute,
});

const projectDetailRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/projects/$projectName",
  component: ProjectDetailRoute,
});

const projectBranchesRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/projects/$projectName/branches",
  component: ProjectBranchesRoute,
});

const projectTagsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/projects/$projectName/tags",
  component: ProjectTagsRoute,
});

const pipelinesRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/pipelines",
  component: PipelinesRoute,
});

const pipelineDetailRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/pipelines/$pipelineId",
  component: PipelineDetailRoute,
});

const buildsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/builds",
  component: BuildsRoute,
});

const buildsIndexRoute = createRoute({
  getParentRoute: () => buildsRoute,
  path: "/",
  component: BuildsIndexRoute,
});

const jobDetailRoute = createRoute({
  getParentRoute: () => buildsRoute,
  path: "/$jobId",
  component: JobDetailRoute,
});

const buildDetailRoute = createRoute({
  getParentRoute: () => jobDetailRoute,
  path: "/builds/$buildId",
  component: BuildDetailRoute,
});

const workersRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/workers",
  component: WorkersRoute,
});

const workersIndexRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/",
  beforeLoad: () => {
    throw redirect({ to: "/workers/overview" });
  },
});

const workersOverviewRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/overview",
  component: WorkersOverviewRoute,
});

const workersProjectsRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/projects",
  component: WorkersProjectsRoute,
});

const workersProjectDetailRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/projects/$projectName",
  component: WorkersProjectDetailRoute,
});

const workersPodsRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/pods",
  component: WorkersPodsRoute,
});

const workersPodDetailRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/pods/$podName",
  component: WorkersPodDetailRoute,
});

const workersDeploymentsRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/deployments",
  component: WorkersDeploymentsRoute,
});

const workersDeploymentDetailRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/deployments/$deploymentName",
  component: WorkersDeploymentDetailRoute,
});

const workersBuildsRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/builds",
  component: WorkersBuildsRoute,
});

const workersBuildDetailRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/builds/$buildName",
  component: WorkersBuildDetailRoute,
});

const workersRoutesRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/routes",
  component: WorkersRoutesRoute,
});

const workersRouteDetailRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/routes/$routeName",
  component: WorkersRouteDetailRoute,
});

const workersServicesRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/services",
  component: WorkersServicesRoute,
});

const workersServiceDetailRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/services/$serviceName",
  component: WorkersServiceDetailRoute,
});

const workersPVCsRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/persistentvolumeclaims",
  component: WorkersPVCsRoute,
});

const workersPVCDetailRoute = createRoute({
  getParentRoute: () => workersRoute,
  path: "/persistentvolumeclaims/$claimName",
  component: WorkersPVCDetailRoute,
});

const artifactsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/artifacts",
  component: ArtifactsRoute,
});

const artifactsIndexRoute = createRoute({
  getParentRoute: () => artifactsRoute,
  path: "/",
  component: ArtifactsIndexRoute,
  validateSearch: (
    search: Record<string, unknown>,
  ): Record<string, unknown> => {
    return {
      q: typeof search.q === "string" && search.q.length > 0 ? search.q : undefined,
      format: search.format,
      repository:
        typeof search.repository === "string" && search.repository.length > 0
          ? search.repository
          : undefined,
      groupId:
        typeof search.groupId === "string" && search.groupId.length > 0
          ? search.groupId
          : undefined,
      artifactId:
        typeof search.artifactId === "string" && search.artifactId.length > 0
          ? search.artifactId
          : undefined,
      version:
        typeof search.version === "string" && search.version.length > 0
          ? search.version
          : undefined,
      classifier:
        typeof search.classifier === "string" && search.classifier.length > 0
          ? search.classifier
          : undefined,
      extension:
        typeof search.extension === "string" && search.extension.length > 0
          ? search.extension
          : undefined,
      checksum:
        typeof search.checksum === "string" && search.checksum.length > 0
          ? search.checksum
          : undefined,
    };
  },
});

const artifactDetailRoute = createRoute({
  getParentRoute: () => artifactsRoute,
  path: "/$componentId",
  component: ArtifactDetailRoute,
});

const artifactSettingsRoute = createRoute({
  getParentRoute: () => artifactsRoute,
  path: "/settings",
  component: ArtifactSettingsRoute,
});

const cacheRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/cache",
  component: CacheRoute,
});

const credentialsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/credentials",
  component: CredentialsRoute,
});

const secretsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/secrets",
  component: SecretsRoute,
});

const secretDetailRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/secrets/$secretId",
  component: SecretDetailRoute,
});

const settingsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/settings",
  component: SettingsRoute,
});

const releasesRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/releases",
  component: ReleasesRoute,
});

const releasesIndexRoute = createRoute({
  getParentRoute: () => releasesRoute,
  path: "/",
  component: ReleasesIndexRoute,
});

const releasesCalendarRoute = createRoute({
  getParentRoute: () => releasesRoute,
  path: "/calendar",
  component: ReleasesCalendarRoute,
  validateSearch: (search: Record<string, unknown>): Record<string, unknown> => {
    return {
      year:
        typeof search.year === "number"
          ? search.year
          : typeof search.year === "string"
            ? Number.parseInt(search.year, 10)
            : undefined,
      month:
        typeof search.month === "number"
          ? search.month
          : typeof search.month === "string"
            ? Number.parseInt(search.month, 10)
            : undefined,
    };
  },
});

const releasesArtifactsRoute = createRoute({
  getParentRoute: () => releasesRoute,
  path: "/artifacts",
  component: ReleasesArtifactsRoute,
});

const releaseDetailRoute = createRoute({
  getParentRoute: () => releasesRoute,
  path: "/$releaseName",
  component: ReleaseDetailRoute,
});

const routeTree = rootRoute.addChildren([
  loginRoute,
  dashboardRoute,
  projectsRoute,
  projectDetailRoute,
  projectBranchesRoute,
  projectTagsRoute,
  pipelinesRoute,
  pipelineDetailRoute,
  buildsRoute.addChildren([
    buildsIndexRoute,
    jobDetailRoute.addChildren([buildDetailRoute]),
  ]),
  workersRoute.addChildren([
    workersIndexRoute,
    workersOverviewRoute,
    workersProjectsRoute,
    workersProjectDetailRoute,
    workersPodsRoute,
    workersPodDetailRoute,
    workersDeploymentsRoute,
    workersDeploymentDetailRoute,
    workersBuildsRoute,
    workersBuildDetailRoute,
    workersRoutesRoute,
    workersRouteDetailRoute,
    workersServicesRoute,
    workersServiceDetailRoute,
    workersPVCsRoute,
    workersPVCDetailRoute,
  ]),
  artifactsRoute.addChildren([
    artifactsIndexRoute,
    artifactDetailRoute,
    artifactSettingsRoute,
  ]),
  cacheRoute,
  credentialsRoute,
  secretsRoute,
  secretDetailRoute,
  settingsRoute,
  releasesRoute.addChildren([
    releasesIndexRoute,
    releasesCalendarRoute,
    releasesArtifactsRoute,
    releaseDetailRoute,
  ]),
]);

export { routeTree };
