import { Search, XIcon, SlidersHorizontal } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";
import type { Release } from "@/types/release";

export type FilterState = {
  search: string;
  environments: string[];
  statuses: string[];
  teams: string[];
  stageDateFrom: string;
  stageDateTo: string;
  prodDateFrom: string;
  prodDateTo: string;
};

export const defaultFilterState: FilterState = {
  search: "",
  environments: [],
  statuses: [],
  teams: [],
  stageDateFrom: "",
  stageDateTo: "",
  prodDateFrom: "",
  prodDateTo: "",
};

const allEnvironments = ["STG", "QA1", "QA2", "PRD", "IN2", "PRE"];
const allStatuses = [
  "initialized",
  "open",
  "in qa",
  "qa certified",
  "stage certified",
  "released",
  "canceled",
  "archived",
];

function countBy<T>(items: Release[], key: (r: Release) => T): Map<T, number> {
  const counts = new Map<T, number>();
  for (const item of items) {
    const k = key(item);
    counts.set(k, (counts.get(k) ?? 0) + 1);
  }
  return counts;
}

interface ReleasesTableToolbarProps {
  filter: FilterState;
  onFilterChange: (filter: FilterState) => void;
  data: Release[];
  isDrawerOpen: boolean;
  onToggleDrawer: () => void;
  hideDrawer?: boolean;
  drawerOnly?: boolean;
}

export function ReleasesTableToolbar({
  filter,
  onFilterChange,
  data,
  isDrawerOpen,
  onToggleDrawer,
  hideDrawer = false,
  drawerOnly = false,
}: ReleasesTableToolbarProps) {
  const activeFilterCount =
    filter.environments.length +
    filter.statuses.length +
    filter.teams.length +
    (filter.stageDateFrom || filter.stageDateTo ? 1 : 0) +
    (filter.prodDateFrom || filter.prodDateTo ? 1 : 0);

  function update(partial: Partial<FilterState>) {
    onFilterChange({ ...filter, ...partial });
  }

  function clearAll() {
    onFilterChange(defaultFilterState);
  }

  function removeEnv(env: string) {
    update({ environments: filter.environments.filter((e) => e !== env) });
  }

  function removeStatus(status: string) {
    update({ statuses: filter.statuses.filter((s) => s !== status) });
  }

  function removeTeam(team: string) {
    update({ teams: filter.teams.filter((t) => t !== team) });
  }

  // For computing faceted counts (only cross-category)
  function filteredWithout(
    category: "environments" | "statuses" | "teams",
  ): Release[] {
    return data.filter((r) => {
      if (filter.search) {
        const q = filter.search.toLowerCase();
        const matchesSearch =
          r.name.toLowerCase().includes(q) ||
          `${r.id}`.includes(q) ||
          r.team.toLowerCase().includes(q) ||
          r.defaultEnv.toLowerCase().includes(q) ||
          r.status.toLowerCase().includes(q) ||
          r.scrumMaster.toLowerCase().includes(q);
        if (!matchesSearch) return false;
      }
      if (category !== "environments" && filter.environments.length > 0) {
        if (!filter.environments.includes(r.defaultEnv)) return false;
      }
      if (category !== "statuses" && filter.statuses.length > 0) {
        if (!filter.statuses.includes(r.status)) return false;
      }
      if (category !== "teams" && filter.teams.length > 0) {
        if (!filter.teams.includes(r.team)) return false;
      }
      return true;
    });
  }

  const envFacetCounts = countBy(filteredWithout("environments"), (r) => r.defaultEnv);
  const statusFacetCounts = countBy(filteredWithout("statuses"), (r) => r.status);
  const teams = [...new Set(data.map((r) => r.team))].sort();
  const teamFacetCounts = countBy(filteredWithout("teams"), (r) => r.team);

  const pills: { id: string; label: string; onRemove: () => void }[] = [];
  for (const env of filter.environments) {
    pills.push({ id: `env-${env}`, label: env, onRemove: () => removeEnv(env) });
  }
  for (const s of filter.statuses) {
    pills.push({ id: `status-${s}`, label: s, onRemove: () => removeStatus(s) });
  }
  for (const t of filter.teams) {
    pills.push({ id: `team-${t}`, label: t, onRemove: () => removeTeam(t) });
  }
  if (filter.stageDateFrom || filter.stageDateTo) {
    const label = `Stage: ${filter.stageDateFrom || "..."} – ${filter.stageDateTo || "..."}`;
    pills.push({
      id: "stage-date",
      label,
      onRemove: () => update({ stageDateFrom: "", stageDateTo: "" }),
    });
  }
  if (filter.prodDateFrom || filter.prodDateTo) {
    const label = `Prod: ${filter.prodDateFrom || "..."} – ${filter.prodDateTo || "..."}`;
    pills.push({
      id: "prod-date",
      label,
      onRemove: () => update({ prodDateFrom: "", prodDateTo: "" }),
    });
  }

  return (
    <div className="space-y-2">
      {!drawerOnly && (
      <div className="flex items-center gap-2">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-2.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground pointer-events-none" />
          <Input
            placeholder="Search releases..."
            value={filter.search}
            onChange={(e) => update({ search: e.target.value })}
            className="h-8 pl-8"
          />
        </div>
        <Button
          variant="outline"
          size="sm"
          onClick={onToggleDrawer}
          className={cn(
            "relative h-8",
            isDrawerOpen && "bg-accent text-accent-foreground",
          )}
        >
          <SlidersHorizontal className="mr-1.5 size-3.5" />
          Filter
          {activeFilterCount > 0 && (
            <Badge
              variant="secondary"
              className="ml-1.5 size-4 rounded-full p-0 text-[10px] font-medium tabular-nums leading-none flex items-center justify-center"
            >
              {activeFilterCount}
            </Badge>
          )}
        </Button>
        {pills.length > 0 && (
          <div className="flex flex-wrap items-center gap-1.5">
            {pills.map((pill) => (
              <Badge
                key={pill.id}
                variant="secondary"
                className="h-6 gap-1 px-2 text-xs font-normal"
              >
                {pill.label}
                <button
                  type="button"
                  onClick={pill.onRemove}
                  className="ml-0.5 rounded-full hover:bg-gray-200/90 p-0.5"
                >
                  <XIcon className="size-3" />
                  <span className="sr-only">Remove {pill.label} filter</span>
                </button>
              </Badge>
            ))}
            <button
              type="button"
              onClick={clearAll}
              className="text-xs text-muted-foreground hover:text-foreground underline"
            >
              Clear all
            </button>
          </div>
        )}
      </div>
      )}

      {isDrawerOpen && !hideDrawer && (
        <div className="border rounded-md p-4 bg-card space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="space-y-2">
              <Label className="text-xs font-medium text-muted-foreground">Environment</Label>
              <div className="space-y-1">
                {allEnvironments.map((env) => {
                  const count = envFacetCounts.get(env) ?? 0;
                  const isChecked = filter.environments.includes(env);
                  const id = `filter-env-${env}`;
                  return (
                    <div
                      key={env}
                      className="flex items-center gap-2 rounded-sm px-1 py-1 text-sm hover:bg-gray-200/90"
                    >
                      <Checkbox
                        id={id}
                        checked={isChecked}
                        onCheckedChange={() => {
                          update({
                            environments: isChecked
                              ? filter.environments.filter((e) => e !== env)
                              : [...filter.environments, env],
                          });
                        }}
                      />
                      <label htmlFor={id} className="flex items-center gap-3 cursor-pointer min-w-0">
                        <span className="truncate">{env}</span>
                        <span className="text-xs text-muted-foreground tabular-nums shrink-0">
                          {count}
                        </span>
                      </label>
                    </div>
                  );
                })}
              </div>
            </div>

            <div className="space-y-2">
              <Label className="text-xs font-medium text-muted-foreground">Status</Label>
              <div className="space-y-1">
                {allStatuses.map((s) => {
                  const count = statusFacetCounts.get(s) ?? 0;
                  const isChecked = filter.statuses.includes(s);
                  const id = `filter-status-${s}`;
                  return (
                    <div
                      key={s}
                      className="flex items-center gap-2 rounded-sm px-1 py-1 text-sm hover:bg-gray-200/90"
                    >
                      <Checkbox
                        id={id}
                        checked={isChecked}
                        onCheckedChange={() => {
                          update({
                            statuses: isChecked
                              ? filter.statuses.filter((st) => st !== s)
                              : [...filter.statuses, s],
                          });
                        }}
                      />
                      <label htmlFor={id} className="flex items-center gap-3 cursor-pointer min-w-0">
                        <span className="truncate">{s}</span>
                        <span className="text-xs text-muted-foreground tabular-nums shrink-0">
                          {count}
                        </span>
                      </label>
                    </div>
                  );
                })}
              </div>
            </div>

            <div className="space-y-2">
              <Label className="text-xs font-medium text-muted-foreground">Team</Label>
              <div className="space-y-1">
                {teams.map((t) => {
                  const count = teamFacetCounts.get(t) ?? 0;
                  const isChecked = filter.teams.includes(t);
                  const id = `filter-team-${t}`;
                  return (
                    <div
                      key={t}
                      className="flex items-center gap-2 rounded-sm px-1 py-1 text-sm hover:bg-gray-200/90"
                    >
                      <Checkbox
                        id={id}
                        checked={isChecked}
                        onCheckedChange={() => {
                          update({
                            teams: isChecked
                              ? filter.teams.filter((tm) => tm !== t)
                              : [...filter.teams, t],
                          });
                        }}
                      />
                      <label htmlFor={id} className="flex items-center gap-3 cursor-pointer min-w-0">
                        <span className="truncate">{t}</span>
                        <span className="text-xs text-muted-foreground tabular-nums shrink-0">
                          {count}
                        </span>
                      </label>
                    </div>
                  );
                })}
              </div>
            </div>

            <div className="space-y-4">
              <div className="space-y-2">
                <Label className="text-xs font-medium text-muted-foreground">Stage Date</Label>
                <div className="flex items-center gap-2">
                  <Input
                    type="date"
                    value={filter.stageDateFrom}
                    onChange={(e) => {
                      const val = e.target.value;
                      update({
                        stageDateFrom: val,
                        ...(val && filter.stageDateTo && val > filter.stageDateTo
                          ? { stageDateTo: val }
                          : {}),
                      });
                    }}
                    className="h-8 text-xs"
                    placeholder="From"
                  />
                  <span className="text-xs text-muted-foreground">–</span>
                  <Input
                    type="date"
                    value={filter.stageDateTo}
                    min={filter.stageDateFrom || undefined}
                    onChange={(e) => update({ stageDateTo: e.target.value })}
                    className="h-8 text-xs"
                    placeholder="To"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <Label className="text-xs font-medium text-muted-foreground">Prod Date</Label>
                <div className="flex items-center gap-2">
                  <Input
                    type="date"
                    value={filter.prodDateFrom}
                    onChange={(e) => {
                      const val = e.target.value;
                      update({
                        prodDateFrom: val,
                        ...(val && filter.prodDateTo && val > filter.prodDateTo
                          ? { prodDateTo: val }
                          : {}),
                      });
                    }}
                    className="h-8 text-xs"
                    placeholder="From"
                  />
                  <span className="text-xs text-muted-foreground">–</span>
                  <Input
                    type="date"
                    value={filter.prodDateTo}
                    min={filter.prodDateFrom || undefined}
                    onChange={(e) => update({ prodDateTo: e.target.value })}
                    className="h-8 text-xs"
                    placeholder="To"
                  />
                </div>
              </div>
            </div>
          </div>

          <div className="flex justify-end">
            <Button variant="ghost" size="sm" onClick={clearAll} className="h-8 text-xs">
              Reset all
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}
