import type { LoginRequest, LoginResponse, User } from "../types/auth";
import { apiClient } from "./client";

export async function login(request: LoginRequest): Promise<LoginResponse> {
  return apiClient.post<LoginResponse>("/auth/login", request);
}

export async function logout(_token?: string): Promise<void> {
  return apiClient.post<void>("/auth/logout", {});
}

export async function whoami(_token?: string): Promise<User> {
  return apiClient.get<User>("/auth/whoami");
}

