import type {
  Credential,
  CredentialListResponse,
  CredentialUsageRecord,
} from "@/types/credentials";
import { apiClient } from "./client";

export async function listCredentials(
  token: string | undefined,
  limit = 20,
): Promise<CredentialListResponse> {
  return apiClient.get(`/credentials?limit=${limit}`, token);
}

export async function getCredential(token: string | undefined, id: string): Promise<Credential> {
  return apiClient.get(`/credentials/${id}`, token);
}

export async function createCredential(
  token: string | undefined,
  data: {
    name: string;
    kind: string;
    label?: string;
    description?: string;
    tags?: string[];
  },
): Promise<Credential> {
  return apiClient.post("/credentials", data, token);
}

export async function updateCredential(
  token: string | undefined,
  id: string,
  data: {
    name?: string;
    label?: string;
    description?: string;
    tags?: string[];
    status?: string;
  },
): Promise<Credential> {
  return apiClient.patch(`/credentials/${id}`, data, token);
}

export async function deleteCredential(token: string | undefined, id: string): Promise<void> {
  return apiClient.delete(`/credentials/${id}`, token);
}

export async function rotateCredential(
  token: string | undefined,
  id: string,
  reason?: string,
): Promise<Credential> {
  return apiClient.post(
    `/credentials/${id}/rotate`,
    { reason: reason || "manual rotation" },
    token,
  );
}

export async function getCredentialUsage(
  token: string | undefined,
  id: string,
): Promise<CredentialUsageRecord[]> {
  return apiClient.get(`/credentials/${id}/usage`, token);
}
