import { useState } from "react";
import { Info } from "lucide-react";
import {
  Combobox,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxInput,
  ComboboxItem,
  ComboboxList,
} from "@/components/ui/combobox";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import {
  type Release,
  type ReleaseFormData,
} from "@/types/release";

const mockUsers = [
  "Alice Chen",
  "Bob Martinez",
  "Carol Nguyen",
  "David Kim",
  "Eve Johnson",
  "Frank Lee",
  "Grace Wang",
  "Henry Brown",
];

const persistentTeams = [
  "Platform",
  "Payments",
  "Identity",
  "Growth",
  "Mobile",
  "Data infra",
];

interface ReleaseDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  release?: Release;
  onSave: (data: ReleaseFormData) => void;
}

export function ReleaseDialog({ open, onOpenChange, release, onSave }: ReleaseDialogProps) {
  const isEdit = !!release;

  const [releaseType, setReleaseType] = useState<"Release" | "Hotfix">(
    release?.releaseType ?? "Release",
  );
  const [name, setName] = useState(release?.name ?? "");
  const [fixVersion, setFixVersion] = useState(release?.fixVersion ?? "");
  const [codeMergeDate, setCodeMergeDate] = useState(release?.codeMergeDate ?? "");
  const [qaDate, setQaDate] = useState(release?.qaDate ?? "");
  const [uatDate, setUatDate] = useState(release?.uatDate ?? "");
  const [stageDate, setStageDate] = useState(release?.stageDate ?? "");
  const [rollbackTestingDate, setRollbackTestingDate] = useState(
    release?.rollbackTestingDate ?? "",
  );
  const [productionDate, setProductionDate] = useState(release?.productionDate ?? "");
  const [productionTime, setProductionTime] = useState(release?.productionTime ?? "");
  const [mainReleaseTicket, setMainReleaseTicket] = useState(release?.mainReleaseTicket ?? "");
  const [prdTicket, setPrdTicket] = useState(release?.prdTicket ?? "");
  const [stgTicket, setStgTicket] = useState(release?.stgTicket ?? "");
  const [qaTicket, setQaTicket] = useState(release?.qaTicket ?? "");
  const [dbaResource, setDbaResource] = useState(release?.dbaResource ?? "");
  const [linuxOpsResource, setLinuxOpsResource] = useState(release?.linuxOpsResource ?? "");
  const [releaseAnalystResource, setReleaseAnalystResource] = useState(
    release?.releaseAnalystResource ?? "",
  );
  const [persistentTeam, setPersistentTeam] = useState(release?.persistentTeam ?? "");
  const [createSdlcBranch, setCreateSdlcBranch] = useState(
    release?.createSdlcBranch ?? false,
  );
  const [autoDeploy, setAutoDeploy] = useState(release?.autoDeploy ?? false);

  function handleSave() {
    onSave({
      releaseType,
      name,
      fixVersion,
      codeMergeDate,
      qaDate,
      uatDate,
      stageDate: stageDate.slice(0, 10),
      rollbackTestingDate,
      productionDate,
      productionTime,
      mainReleaseTicket,
      prdTicket,
      stgTicket,
      qaTicket,
      dbaResource,
      linuxOpsResource,
      releaseAnalystResource,
      persistentTeam,
      createSdlcBranch,
      autoDeploy,
    });
  }

  function handleOpenChange(open: boolean) {
    if (!open) {
      if (!isEdit) {
        setReleaseType("Release");
        setName("");
        setFixVersion("");
        setCodeMergeDate("");
        setQaDate("");
        setUatDate("");
        setStageDate("");
        setRollbackTestingDate("");
        setProductionDate("");
        setProductionTime("");
        setMainReleaseTicket("");
        setPrdTicket("");
        setStgTicket("");
        setQaTicket("");
        setDbaResource("");
        setLinuxOpsResource("");
        setReleaseAnalystResource("");
        setPersistentTeam("");
        setCreateSdlcBranch(false);
        setAutoDeploy(false);
      }
    }
    onOpenChange(open);
  }

  function InfoTooltip({ content }: { content: string }) {
    return (
      <TooltipProvider>
        <Tooltip>
          <TooltipTrigger asChild>
            <span className="inline-flex cursor-help text-muted-foreground hover:text-foreground">
              <Info className="size-3.5" />
            </span>
          </TooltipTrigger>
          <TooltipContent side="top" className="max-w-64 text-xs">
            {content}
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
    );
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent
        className="sm:max-w-2xl max-h-[90vh] overflow-y-auto"
        onOpenAutoFocus={(e: Event) => e.preventDefault()}
      >
        <DialogHeader>
          <DialogTitle>{isEdit ? "Edit release" : "Create release"}</DialogTitle>
          <DialogDescription>
            {isEdit
              ? "Update the release details below."
              : "Fill in the details to create a new release."}
          </DialogDescription>
        </DialogHeader>

        <div className="grid gap-5">
          {/* Release Type */}
          <div className="grid gap-2">
            <Label>Release Type</Label>
            <div className="flex items-center gap-6">
              <label className="flex items-center gap-2 text-sm cursor-pointer">
                <input
                  type="radio"
                  name="releaseType"
                  checked={releaseType === "Release"}
                  onChange={() => setReleaseType("Release")}
                  className="accent-foreground"
                />
                Release
              </label>
              <label className="flex items-center gap-2 text-sm cursor-pointer">
                <input
                  type="radio"
                  name="releaseType"
                  checked={releaseType === "Hotfix"}
                  onChange={() => setReleaseType("Hotfix")}
                  className="accent-foreground"
                />
                Hotfix
              </label>
            </div>
          </div>

          {/* Release Name + Fix Version */}
          <div className="grid grid-cols-2 gap-4">
            <div className="grid gap-2">
              <Label htmlFor="release-name">Release Name</Label>
              <Input
                id="release-name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="e.g. release/ABC123"
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="fix-version">Fix Version</Label>
              <Input
                id="fix-version"
                value={fixVersion}
                onChange={(e) => setFixVersion(e.target.value)}
                placeholder="e.g. 1.2.3"
              />
            </div>
          </div>

          {isEdit && release && (
            <div className="grid gap-2">
              <Label htmlFor="release-id">Release ID</Label>
              <Input
                id="release-id"
                value={`REL-${release.id}`}
                readOnly
                className="text-muted-foreground"
              />
            </div>
          )}

          {/* Date fields */}
          <div className="grid grid-cols-3 gap-3">
            <div className="grid gap-2">
              <Label htmlFor="code-merge-date">Code Merge Date</Label>
              <Input
                id="code-merge-date"
                type="date"
                value={codeMergeDate}
                onChange={(e) => setCodeMergeDate(e.target.value)}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="qa-date">QA Date</Label>
              <Input
                id="qa-date"
                type="date"
                value={qaDate}
                onChange={(e) => setQaDate(e.target.value)}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="uat-date">UAT Date</Label>
              <Input
                id="uat-date"
                type="date"
                value={uatDate}
                onChange={(e) => setUatDate(e.target.value)}
              />
            </div>
          </div>

          <div className="grid grid-cols-3 gap-3">
            <div className="grid gap-2">
              <Label htmlFor="stage-date">Stage Date</Label>
              <Input
                id="stage-date"
                type="date"
                value={stageDate ? stageDate.slice(0, 10) : ""}
                onChange={(e) => setStageDate(e.target.value)}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="rollback-date">Rollback Testing Date</Label>
              <Input
                id="rollback-date"
                type="date"
                value={rollbackTestingDate}
                onChange={(e) => setRollbackTestingDate(e.target.value)}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="production-date">Production Date</Label>
              <Input
                id="production-date"
                type="date"
                value={productionDate}
                onChange={(e) => setProductionDate(e.target.value)}
              />
            </div>
          </div>

          {/* Production Time */}
          <div className="grid grid-cols-2 gap-4">
            <div className="grid gap-2">
              <Label htmlFor="prod-time">Production Time (24h)</Label>
              <Input
                id="prod-time"
                type="time"
                value={productionTime}
                onChange={(e) => setProductionTime(e.target.value)}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="persistent-team">Persistent Team</Label>
              <Select value={persistentTeam} onValueChange={setPersistentTeam}>
                <SelectTrigger id="persistent-team">
                  <SelectValue placeholder="Select team" />
                </SelectTrigger>
                <SelectContent>
                  {persistentTeams.map((t) => (
                    <SelectItem key={t} value={t}>
                      {t}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Tickets */}
          <div className="grid grid-cols-2 gap-4">
            <div className="grid gap-2">
              <Label htmlFor="main-ticket">Main Release Ticket</Label>
              <Input
                id="main-ticket"
                value={mainReleaseTicket}
                onChange={(e) => setMainReleaseTicket(e.target.value)}
                placeholder="e.g. REL-1234"
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="prd-ticket">PRD Ticket</Label>
              <Input
                id="prd-ticket"
                value={prdTicket}
                onChange={(e) => setPrdTicket(e.target.value)}
                placeholder="e.g. PRD-5678"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="grid gap-2">
              <Label htmlFor="stg-ticket">STG Ticket</Label>
              <Input
                id="stg-ticket"
                value={stgTicket}
                onChange={(e) => setStgTicket(e.target.value)}
                placeholder="e.g. STG-9012"
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="qa-ticket">QA Ticket</Label>
              <Input
                id="qa-ticket"
                value={qaTicket}
                onChange={(e) => setQaTicket(e.target.value)}
                placeholder="e.g. QA-3456"
              />
            </div>
          </div>

          {/* Resource lookups */}
          <div className="grid grid-cols-3 gap-3">
            <div className="grid gap-2">
              <Label htmlFor="dba-resource">DBA Resource</Label>
              <Combobox items={mockUsers} value={dbaResource} onValueChange={(v) => setDbaResource(v ?? "")}>
                <ComboboxInput placeholder="Search user..." showTrigger />
                <ComboboxContent>
                  <ComboboxEmpty>No users found.</ComboboxEmpty>
                  <ComboboxList>
                    {(item) => (
                      <ComboboxItem key={item} value={item}>
                        {item}
                      </ComboboxItem>
                    )}
                  </ComboboxList>
                </ComboboxContent>
              </Combobox>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="ops-resource">Linux OPS Resource</Label>
              <Combobox items={mockUsers} value={linuxOpsResource} onValueChange={(v) => setLinuxOpsResource(v ?? "")}>
                <ComboboxInput placeholder="Search user..." showTrigger />
                <ComboboxContent>
                  <ComboboxEmpty>No users found.</ComboboxEmpty>
                  <ComboboxList>
                    {(item) => (
                      <ComboboxItem key={item} value={item}>
                        {item}
                      </ComboboxItem>
                    )}
                  </ComboboxList>
                </ComboboxContent>
              </Combobox>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="analyst-resource">Release Analyst Resource</Label>
              <Combobox items={mockUsers} value={releaseAnalystResource} onValueChange={(v) => setReleaseAnalystResource(v ?? "")}>
                <ComboboxInput placeholder="Search user..." showTrigger />
                <ComboboxContent>
                  <ComboboxEmpty>No users found.</ComboboxEmpty>
                  <ComboboxList>
                    {(item) => (
                      <ComboboxItem key={item} value={item}>
                        {item}
                      </ComboboxItem>
                    )}
                  </ComboboxList>
                </ComboboxContent>
              </Combobox>
            </div>
          </div>

          {/* Checkboxes */}
          <div className="flex items-center gap-6 pt-2">
            <label className="flex items-center gap-2 text-sm cursor-pointer">
              <input
                type="checkbox"
                checked={createSdlcBranch}
                onChange={(e) => setCreateSdlcBranch(e.target.checked)}
                className="accent-foreground size-4"
              />
              Create SDLC Branch
              <InfoTooltip content="Automatically creates a new SDLC branch from the main branch when the release is created." />
            </label>
            <label className="flex items-center gap-2 text-sm cursor-pointer">
              <input
                type="checkbox"
                checked={autoDeploy}
                onChange={(e) => setAutoDeploy(e.target.checked)}
                className="accent-foreground size-4"
              />
              Auto Deploy (optional)
              <InfoTooltip content="When enabled, the release will be automatically deployed to the target environment upon approval." />
            </label>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => handleOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={!name.trim()}>
            {isEdit ? "Save changes" : "Create release"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
