import type { CacheEntry, PaginatedResponse } from "../types/cache";
import { apiClient } from "./client";

export async function listCacheEntries(
  token: string,
  limit = 50,
): Promise<PaginatedResponse<CacheEntry>> {
  const params = new URLSearchParams({ limit: String(limit) });
  const data = await apiClient.get<CacheEntry[]>(`/caches?${params.toString()}`, token);
  if (Array.isArray(data)) {
    return { items: data, total: data.length };
  }
  return { items: [], total: 0 };
}

export async function getCacheEntry(id: string, token: string): Promise<CacheEntry> {
  return apiClient.get<CacheEntry>(`/caches/${id}`, token);
}

export async function deleteCacheEntry(id: string, token: string): Promise<void> {
  await apiClient.delete<void>(`/caches/${id}`, token);
}
