import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import type { Component, SearchFilters, UploadArtifactRequest } from "./types";
import {
  addMockComponent,
  getComponentById,
  mockRecentSearches,
  searchComponents,
} from "./mock-data";

function fakeDelay(ms = 200): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Search / browse components matching the given filters.
 *
 * When no filters are provided, returns the full component list (browse mode).
 * Query key is filter-driven (`["artifacts", "search", filters]`) so that
 * changing any filter produces a new cache entry.  When a real backend is
 * available, replace the `queryFn` body with a `fetch` call — no consumer
 * changes needed.
 */
export function useArtifactSearch(filters: SearchFilters) {
  return useQuery({
    queryKey: ["artifacts", "search", filters],
    queryFn: async () => {
      await fakeDelay();
      return searchComponents(filters);
    },
  });
}

/**
 * Fetch full detail for a single component by its id.
 */
export function useArtifactDetail(componentId: string) {
  return useQuery({
    queryKey: ["artifacts", "detail", componentId],
    queryFn: async () => {
      await fakeDelay();
      const component = getComponentById(componentId);
      if (!component) {
        throw new Error(`Component not found: ${componentId}`);
      }
      return component as Component;
    },
    enabled: !!componentId,
  });
}

/**
 * Return the list of recent searches (static / mocked for now).
 */
export function useRecentSearches() {
  return useQuery({
    queryKey: ["artifacts", "recent-searches"],
    queryFn: async () => {
      await fakeDelay(100);
      return mockRecentSearches;
    },
    staleTime: Infinity,
  });
}

/**
 * Upload a new artifact (mocked — adds to in-memory dataset).
 */
export function useUploadArtifact() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (req: UploadArtifactRequest) => {
      await fakeDelay(600);
      return addMockComponent(req);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["artifacts", "search"] });
    },
  });
}
