import { KeyRound, Loader2 } from "lucide-react";
import { type FormEvent, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useAuth } from "../../hooks/use-auth";

export function LoginForm() {
  const { login, isLoggingIn, loginError } = useAuth();
  const [token, setToken] = useState("");
  const [validationError, setValidationError] = useState<string | null>(null);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setValidationError(null);

    if (!token.trim()) {
      setValidationError("Token is required");
      return;
    }

    try {
      await login({ token: token.trim() });
    } catch {
      // error is captured in loginError
    }
  };

  const error = validationError ?? loginError?.message ?? null;

  return (
    <div className="flex flex-col gap-6">
      <div className="rounded-xl border bg-card text-card-foreground shadow-sm">
        <div className="flex flex-col gap-1 p-6 pb-0 text-center">
          <h2 className="text-xl font-semibold whitespace-nowrap">Sign in to Maple</h2>
          <p className="text-sm text-muted-foreground">Enter your access token to continue</p>
        </div>
        <div className="p-6">
          {isLoggingIn ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="size-6 animate-spin text-muted-foreground" />
            </div>
          ) : (
            <form onSubmit={handleSubmit} noValidate>
              <div className="flex flex-col gap-4">
                {error && (
                  <div
                    className="rounded-md bg-destructive/10 px-3 py-2 text-sm text-destructive"
                    role="alert"
                  >
                    {error}
                  </div>
                )}
                <div className="grid gap-2">
                  <label
                    className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-50"
                    htmlFor="token-input"
                  >
                    Access Token
                  </label>
                  <Input
                    id="token-input"
                    type="password"
                    placeholder="Enter your token"
                    value={token}
                    onChange={(e) => setToken(e.target.value)}
                    autoComplete="current-password"
                    disabled={isLoggingIn}
                  />
                </div>
                <Button type="submit" disabled={isLoggingIn} className="w-full">
                  <KeyRound className="size-4" />
                  Sign In
                </Button>
              </div>
            </form>
          )}
        </div>
      </div>
    </div>
  );
}
