import { useState } from "react";
import { UploadIcon, LoaderIcon } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useUploadArtifact } from "../api/queries";
import type { FormatType, UploadArtifactRequest } from "../api/types";

const FORMAT_OPTIONS: { value: FormatType; label: string }[] = [
  { value: "maven", label: "Maven" },
  { value: "npm", label: "npm" },
  { value: "docker", label: "Docker" },
  { value: "pypi", label: "PyPI" },
  { value: "nuget", label: "NuGet" },
];

interface UploadArtifactDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

const INITIAL_STATE: UploadArtifactRequest = {
  format: "maven",
  repository: "",
  group: "",
  name: "",
  version: "",
  extension: "",
  description: "",
  classifier: "",
};

export function UploadArtifactDialog({ open, onOpenChange }: UploadArtifactDialogProps) {
  const [form, setForm] = useState<UploadArtifactRequest>(INITIAL_STATE);
  const upload = useUploadArtifact();

  function update<K extends keyof UploadArtifactRequest>(
    key: K,
    value: UploadArtifactRequest[K],
  ) {
    setForm((prev) => ({ ...prev, [key]: value }));
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    try {
      await upload.mutateAsync(form);
      setForm(INITIAL_STATE);
      onOpenChange(false);
    } catch {
      // error handled by mutation
    }
  }

  function handleOpenChange(open: boolean) {
    if (!open) {
      setForm(INITIAL_STATE);
      upload.reset();
    }
    onOpenChange(open);
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="sm:max-w-lg">
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle>Upload Artifact</DialogTitle>
            <DialogDescription>
              Manually add a new artifact to the repository.
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-4 py-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label htmlFor="upload-format">Format</Label>
                <Select
                  value={form.format}
                  onValueChange={(v) => update("format", v as FormatType)}
                >
                  <SelectTrigger id="upload-format">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {FORMAT_OPTIONS.map((opt) => (
                      <SelectItem key={opt.value} value={opt.value}>
                        {opt.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="upload-repository">Repository</Label>
                <Input
                  id="upload-repository"
                  placeholder="e.g. maven-releases"
                  value={form.repository}
                  onChange={(e) => update("repository", e.target.value)}
                  required
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label htmlFor="upload-group">Group</Label>
                <Input
                  id="upload-group"
                  placeholder="e.g. com.example"
                  value={form.group}
                  onChange={(e) => update("group", e.target.value)}
                  required
                />
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="upload-name">Name</Label>
                <Input
                  id="upload-name"
                  placeholder="e.g. my-lib"
                  value={form.name}
                  onChange={(e) => update("name", e.target.value)}
                  required
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label htmlFor="upload-version">Version</Label>
                <Input
                  id="upload-version"
                  placeholder="e.g. 1.0.0"
                  value={form.version}
                  onChange={(e) => update("version", e.target.value)}
                  required
                />
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="upload-extension">Extension</Label>
                <Input
                  id="upload-extension"
                  placeholder="e.g. jar"
                  value={form.extension}
                  onChange={(e) => update("extension", e.target.value)}
                  required
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label htmlFor="upload-classifier">Classifier</Label>
                <Input
                  id="upload-classifier"
                  placeholder="e.g. sources (optional)"
                  value={form.classifier ?? ""}
                  onChange={(e) => update("classifier", e.target.value || undefined)}
                />
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="upload-description">Description</Label>
                <Input
                  id="upload-description"
                  placeholder="Optional description"
                  value={form.description ?? ""}
                  onChange={(e) => update("description", e.target.value || undefined)}
                />
              </div>
            </div>
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => handleOpenChange(false)}
              disabled={upload.isPending}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={upload.isPending}>
              {upload.isPending ? (
                <LoaderIcon className="size-4 animate-spin" />
              ) : (
                <UploadIcon className="size-4" />
              )}
              Upload
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}
