import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import * as mockApi from "./mock-data";
import type { Build } from "./types";

export function useJobs() {
  return useQuery({
    queryKey: ["pipelines", "jobs"],
    queryFn: mockApi.fetchJobs,
  });
}

export function useJob(jobId: string) {
  return useQuery({
    queryKey: ["pipelines", "jobs", jobId],
    queryFn: () => mockApi.fetchJob(jobId),
    enabled: !!jobId,
  });
}

export function useBuilds(jobId: string) {
  return useQuery({
    queryKey: ["pipelines", "jobs", jobId, "builds"],
    queryFn: () => mockApi.fetchBuilds(jobId),
    enabled: !!jobId,
    refetchInterval: (query) => {
      const data = query.state.data as Build[] | undefined;
      if (!data) return false;
      const hasActive = data.some(
        (b) => b.status === "running" || b.status === "queued",
      );
      return hasActive ? 3000 : false;
    },
  });
}

export function useBuild(jobId: string, buildId: string) {
  return useQuery({
    queryKey: ["pipelines", "jobs", jobId, "builds", buildId],
    queryFn: () => mockApi.fetchBuild(jobId, buildId),
    enabled: !!jobId && !!buildId,
    refetchInterval: (query) => {
      const data = query.state.data as Build | undefined;
      if (!data) return false;
      return data.status === "running" || data.status === "queued" ? 3000 : false;
    },
  });
}

export function useConsoleLog(buildId: string) {
  const queryClient = useQueryClient();
  const data = queryClient.getQueryData<Build>([
    "pipelines",
    "jobs",
    // can't get jobId here; callers will refetch via the build query interval
  ]);
  const isActive =
    data?.status === "running" || data?.status === "queued";

  return useQuery({
    queryKey: ["pipelines", "logs", buildId],
    queryFn: () => mockApi.fetchConsoleLog(buildId),
    enabled: !!buildId,
    refetchInterval: isActive ? 3000 : false,
  });
}

export function useTriggerBuild() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (jobId: string) => mockApi.triggerBuild(jobId),
    onSuccess: (_data, jobId) => {
      queryClient.invalidateQueries({ queryKey: ["pipelines", "jobs", jobId, "builds"] });
      queryClient.invalidateQueries({ queryKey: ["pipelines", "jobs"] });
    },
  });
}

export function useStopBuild() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ jobId, buildId }: { jobId: string; buildId: string }) =>
      mockApi.stopBuild(jobId, buildId),
    onSuccess: (_data, { jobId, buildId }) => {
      queryClient.invalidateQueries({ queryKey: ["pipelines", "jobs", jobId] });
      queryClient.invalidateQueries({ queryKey: ["pipelines", "jobs", jobId, "builds", buildId] });
      queryClient.invalidateQueries({ queryKey: ["pipelines", "jobs", jobId, "builds"] });
      queryClient.invalidateQueries({ queryKey: ["pipelines", "jobs"] });
    },
  });
}

export function useRecentBuilds() {
  return useQuery({
    queryKey: ["pipelines", "recent-builds"],
    queryFn: mockApi.fetchRecentBuilds,
  });
}
