import type { Secret, SecretListResponse, SecretUsageRecord } from "@/types/secret";
import { apiClient } from "./client";


export async function listSecrets(
  token: string | undefined,
  limit = 20,
): Promise<SecretListResponse> {
  const data = await apiClient.get<Secret[] | SecretListResponse>(
    `/secrets?limit=${limit}`,
    token,
  );
  if (Array.isArray(data)) {
    return { items: data, total: data.length };
  }
  return data;
}

export async function getSecret(token: string | undefined, id: string): Promise<Secret> {
  return apiClient.get<Secret>(`/secrets/${id}`, token);
}

export async function createSecret(
  token: string | undefined,
  data: {
    name: string;
    kind: string;
    label?: string;
    description?: string;
    tags?: string[];
    provider?: string;
    external_reference?: string;
    value?: string;
    folder?: string;
    project?: string;
  },
): Promise<Secret> {
  return apiClient.post("/secrets", data, token);
}

export async function updateSecret(
  token: string | undefined,
  id: string,
  data: {
    name?: string;
    label?: string;
    description?: string;
    tags?: string[];
    status?: string;
    value?: string;
    folder?: string;
    project?: string;
  },
): Promise<Secret> {
  return apiClient.patch(`/secrets/${id}`, data, token);
}

export async function deleteSecret(token: string | undefined, id: string): Promise<void> {
  return apiClient.delete(`/secrets/${id}`, token);
}

export async function rotateSecret(
  token: string | undefined,
  id: string,
  reason?: string,
): Promise<Secret> {
  return apiClient.post(`/secrets/${id}/rotate`, { reason: reason || "manual rotation" }, token);
}

export async function getSecretUsage(
  token: string | undefined,
  id: string,
): Promise<SecretUsageRecord[]> {
  return apiClient.get(`/secrets/${id}/usage`, token);
}
