const consoleLogs: Record<string, LogLine[]> = {};

function generateLogs(buildId: string, build: Build): LogLine[] {
  if (consoleLogs[buildId]) return consoleLogs[buildId];

  const lines: LogLine[] = [];
  const start = new Date(build.createdAt).getTime();
  const isRunning = build.status === "running";
  const isQueued = build.status === "queued";
  const totalLines = isQueued ? 5 : isRunning ? 80 : 120;

  const pseudoStages = build.stages.map((s) => s.name);

  for (let i = 0; i < totalLines; i++) {
    const ts = new Date(start + i * 1500).toISOString();
    const stage = pseudoStages[Math.min(Math.floor(i / (totalLines / pseudoStages.length)), pseudoStages.length - 1)];
    const msgs = [
      `[${stage}] Starting step...`,
      `[${stage}] Running command: ${["npm run build", "go test ./...", "docker build -t app .", "pnpm lint", "npx tsc --noEmit", "deploy.sh staging"][Math.floor(Math.random() * 6)]}`,
      `[${stage}] output: Processing batch ${i + 1}/${totalLines}`,
      `[${stage}] output: Checking status...`,
      `[${stage}] output: ${["OK", "PASS", "SKIPPED", "WARNING: flaky test detected", "info: 12 tests passed", "debug: cache hit for module"][Math.floor(Math.random() * 6)]}`,
    ];
    lines.push({
      lineNumber: i + 1,
      timestamp: ts,
      stream: i % 8 === 3 ? "stderr" : "stdout",
      content: msgs[Math.floor(Math.random() * msgs.length) % msgs.length] as string,
    });
  }

  if (!isRunning && !isQueued) {
    const finalStatus = build.status === "success" ? "SUCCESS" : build.status === "failed" ? "FAILURE" : "UNSTABLE";
    lines.push({
      lineNumber: totalLines + 1,
      timestamp: new Date(start + totalLines * 1500).toISOString(),
      stream: "stdout",
      content: `\nBuild completed: ${finalStatus} (${Math.floor((build.duration ?? 0) / 1000)}s)`,
    });
  }

  if (isQueued) {
    for (let i = 0; i < 5; i++) {
      lines.push({
        lineNumber: i + 1,
        timestamp: new Date(start + i * 5000).toISOString(),
        stream: "stdout",
        content: `Waiting for available runner... (${i + 1}/${5})`,
      });
    }
  }

  consoleLogs[buildId] = lines;
  return lines;
}

const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));


export async function fetchJobs(): Promise<Job[]> {
  await delay(300);
  return jobsData;
}

export async function fetchJob(jobId: string): Promise<Job | null> {
  await delay(200);
  return jobsData.find((j) => j.id === jobId) ?? null;
}

export async function fetchBuilds(jobId: string): Promise<Build[]> {
  await delay(250);
  return jobBuilds[jobId] ?? [];
}

export async function fetchBuild(jobId: string, buildId: string): Promise<Build | null> {
  await delay(200);
  const builds = jobBuilds[jobId] ?? [];
  return builds.find((b) => b.id === buildId) ?? null;
}

export async function fetchConsoleLog(buildId: string): Promise<LogLine[]> {
  await delay(150);
  for (const builds of Object.values(jobBuilds)) {
    const build = builds.find((b) => b.id === buildId);
    if (build) {
      return generateLogs(buildId, build);
    }
  }
  return [];
}

export async function triggerBuild(jobId: string): Promise<Build> {
  await delay(500);
  const job = jobsData.find((j) => j.id === jobId);
  if (!job) throw new Error(`Job ${jobId} not found`);
  const builds = jobBuilds[jobId] ?? [];
  const lastBuild = builds.length > 0 ? builds[builds.length - 1] : null;
  const newBuild: Build = {
    id: `b-${jobId.split("-")[1]}-${(lastBuild?.number ?? 0) + 1}`,
    jobId,
    number: (lastBuild?.number ?? 0) + 1,
    status: "running",
    trigger: "manual",
    branch: job.branch,
    commitHash: `new-${Math.random().toString(16).slice(2, 10)}`,
    commitMessage: "Manual trigger via UI",
    triggeredBy: "You",
    duration: null,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    stages: [
      { name: "Queued", status: "running", duration: null, startedAt: new Date().toISOString(), completedAt: null },
    ],
    artifacts: [],
  };
  jobBuilds[jobId] = [...builds, newBuild];
  job.status = "running";
  job.lastRunAt = newBuild.createdAt;
  return newBuild;
}

export async function stopBuild(jobId: string, buildId: string): Promise<void> {
  await delay(300);
  const builds = jobBuilds[jobId] ?? [];
  const build = builds.find((b) => b.id === buildId);
  if (build) {
    build.status = "aborted";
    build.updatedAt = new Date().toISOString();
    build.stages.forEach((s) => {
      if (s.status === "running" || s.status === "queued") {
        s.status = "aborted";
        s.completedAt = new Date().toISOString();
      }
    });
  }
  const job = jobsData.find((j) => j.id === jobId);
  if (job) {
    const anyRunning = (jobBuilds[jobId] ?? []).some((b) => b.status === "running" || b.status === "queued");
    if (!anyRunning) {
      job.status = "aborted";
    }
  }
}

export async function fetchRecentBuilds(): Promise<Build[]> {
  await delay(200);
  const all: Build[] = [];
  for (const builds of Object.values(jobBuilds)) {
    all.push(...builds.map((b) => ({ ...b })));
  }
  all.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  return all.slice(0, 10);
}
