import type { ColumnDef } from "@tanstack/react-table";
import { format, isToday, isYesterday } from "date-fns";
import { ArrowDownIcon, ArrowUpDownIcon, ArrowUpIcon, MoreHorizontal } from "lucide-react";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import type { Release } from "@/types/release";
import { EnvBadge } from "./env-badge";
import { StatusBadge } from "./status-badge";

function relativeDate(dateStr: string | null): { date: string; label: string } | null {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  const formatted = format(d, "MMM d, yyyy");
  if (isToday(d)) return { date: formatted, label: "Today" };
  if (isYesterday(d)) return { date: formatted, label: "Yesterday" };
  const diff = Math.round((d.getTime() - Date.now()) / (1000 * 60 * 60 * 24));
  if (diff > 0) return { date: formatted, label: `in ${diff}d` };
  if (diff < 0) return { date: formatted, label: `${Math.abs(diff)}d ago` };
  return { date: formatted, label: "Today" };
}

export function createColumns(onEdit?: (release: Release) => void): ColumnDef<Release>[] {
  return [
    {
      accessorKey: "name",
      header: ({ header }) => {
        const sorted = header.column.getIsSorted();
        return (
          <span className="flex items-center gap-1 text-xs font-medium">
            Release
            {sorted === "asc" ? (
              <ArrowUpIcon className="size-3" />
            ) : sorted === "desc" ? (
              <ArrowDownIcon className="size-3" />
            ) : (
              <ArrowUpDownIcon className="size-3 text-muted-foreground/50" />
            )}
          </span>
        );
      },
      cell: ({ row }) => {
        const release = row.original;
        return (
          <div className="flex flex-col">
            <span className="font-medium text-sm">{release.name}</span>
            <span className="text-xs text-muted-foreground">REL-{release.id}</span>
          </div>
        );
      },
      sortingFn: (a, b) => a.original.name.localeCompare(b.original.name),
    },
    {
      id: "artifacts",
      header: ({ header }) => {
        const sorted = header.column.getIsSorted();
        return (
          <span className="flex items-center gap-1 text-xs font-medium">
            Artifacts
            {sorted === "asc" ? (
              <ArrowUpIcon className="size-3" />
            ) : sorted === "desc" ? (
              <ArrowDownIcon className="size-3" />
            ) : (
              <ArrowUpDownIcon className="size-3 text-muted-foreground/50" />
            )}
          </span>
        );
      },
      cell: ({ row }) => (
        <Badge variant="secondary" className="text-xs font-mono">
          {row.original.numberOfArtifacts}
        </Badge>
      ),
      sortingFn: (a, b) => a.original.numberOfArtifacts - b.original.numberOfArtifacts,
      enableSorting: true,
    },
    {
      accessorKey: "defaultEnv",
      header: ({ header }) => {
        const sorted = header.column.getIsSorted();
        return (
          <span className="flex items-center gap-1 text-xs font-medium">
            Default Env
            {sorted === "asc" ? (
              <ArrowUpIcon className="size-3" />
            ) : sorted === "desc" ? (
              <ArrowDownIcon className="size-3" />
            ) : (
              <ArrowUpDownIcon className="size-3 text-muted-foreground/50" />
            )}
          </span>
        );
      },
      cell: ({ row }) => <EnvBadge env={row.original.defaultEnv} />,
    },
    {
      accessorKey: "team",
      header: ({ header }) => {
        const sorted = header.column.getIsSorted();
        return (
          <span className="flex items-center gap-1 text-xs font-medium">
            Team
            {sorted === "asc" ? (
              <ArrowUpIcon className="size-3" />
            ) : sorted === "desc" ? (
              <ArrowDownIcon className="size-3" />
            ) : (
              <ArrowUpDownIcon className="size-3 text-muted-foreground/50" />
            )}
          </span>
        );
      },
      cell: ({ row }) => {
        const team = row.original.team;
        return (
          <div className="flex flex-col">
            <div className="flex items-center gap-2">
              <Avatar size="sm">
                <AvatarFallback className="text-xs font-medium">{team[0]}</AvatarFallback>
              </Avatar>
              <span className="text-sm">{team}</span>
            </div>
            <span className="text-xs text-muted-foreground ml-9">{row.original.scrumMaster}</span>
          </div>
        );
      },
    },
    {
      accessorKey: "stageDate",
      header: ({ header }) => {
        const sorted = header.column.getIsSorted();
        return (
          <span className="flex items-center gap-1 text-xs font-medium">
            Stage Date
            {sorted === "asc" ? (
              <ArrowUpIcon className="size-3" />
            ) : sorted === "desc" ? (
              <ArrowDownIcon className="size-3" />
            ) : (
              <ArrowUpDownIcon className="size-3 text-muted-foreground/50" />
            )}
          </span>
        );
      },
      cell: ({ row }) => {
        const date = row.original.stageDate;
        const rel = relativeDate(date);
        if (!rel) return <span className="text-sm text-muted-foreground">Not scheduled</span>;
        return (
          <div className="flex flex-col">
            <span className="text-sm">{rel.date}</span>
            <span className="text-xs text-muted-foreground">{rel.label}</span>
          </div>
        );
      },
      sortingFn: (a, b) => new Date(a.original.stageDate).getTime() - new Date(b.original.stageDate).getTime(),
    },
    {
      id: "estProdDate",
      header: ({ header }) => {
        const sorted = header.column.getIsSorted();
        return (
          <span className="flex items-center gap-1 text-xs font-medium">
            Prod Date
            {sorted === "asc" ? (
              <ArrowUpIcon className="size-3" />
            ) : sorted === "desc" ? (
              <ArrowDownIcon className="size-3" />
            ) : (
              <ArrowUpDownIcon className="size-3 text-muted-foreground/50" />
            )}
          </span>
        );
      },
      cell: ({ row }) => {
        const date = row.original.estProdDate;
        if (!date) return <span className="text-sm text-muted-foreground">Not scheduled</span>;
        const rel = relativeDate(date);
        if (!rel) return <span className="text-sm text-muted-foreground">Not scheduled</span>;
        return (
          <div className="flex flex-col">
            <span className="text-sm">{rel.date}</span>
            <span className="text-xs text-muted-foreground">{rel.label}</span>
          </div>
        );
      },
      sortingFn: (a, b) =>
        new Date(a.original.estProdDate).getTime() - new Date(b.original.estProdDate).getTime(),
    },
    {
      accessorKey: "status",
      header: ({ header }) => {
        const sorted = header.column.getIsSorted();
        return (
          <span className="flex items-center gap-1 text-xs font-medium">
            Status
            {sorted === "asc" ? (
              <ArrowUpIcon className="size-3" />
            ) : sorted === "desc" ? (
              <ArrowDownIcon className="size-3" />
            ) : (
              <ArrowUpDownIcon className="size-3 text-muted-foreground/50" />
            )}
          </span>
        );
      },
      cell: ({ row }) => <StatusBadge status={row.original.status} />,
    },
    {
      id: "actions",
      enableSorting: false,
      header: () => <div className="w-8" />,
      cell: ({ row }) => (
        <div className="flex justify-end">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="icon" className="size-8">
                <MoreHorizontal className="size-4" />
                <span className="sr-only">Actions</span>
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuItem>View details</DropdownMenuItem>
              <DropdownMenuItem onSelect={() => onEdit?.(row.original)}>Edit release</DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem>Archive release</DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      ),
    },
  ];
}
