import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  createSecret,
  deleteSecret,
  getSecret,
  getSecretUsage,
  listSecrets,
  rotateSecret,
  updateSecret,
} from "@/api/secrets";
import { useAuthStore } from "@/state/auth-store";
import type { CreateSecretRequest, UpdateSecretRequest } from "@/types/secret";

export function useSecrets(limit = 20) {
  const { token, isAuthenticated } = useAuthStore();
  return useQuery({
    queryKey: ["secrets", limit],
    queryFn: () => listSecrets(token ?? undefined, limit),
    enabled: isAuthenticated,
  });
}

export function useSecret(id: string) {
  const { token, isAuthenticated } = useAuthStore();
  return useQuery({
    queryKey: ["secrets", id],
    queryFn: () => getSecret(token ?? undefined, id),
    enabled: isAuthenticated && !!id,
  });
}

export function useCreateSecret() {
  const { token } = useAuthStore();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (data: CreateSecretRequest) => createSecret(token ?? undefined, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["secrets"] });
    },
  });
}

export function useUpdateSecret(id: string) {
  const { token } = useAuthStore();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (data: UpdateSecretRequest) => updateSecret(token ?? undefined, id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["secrets"] });
      queryClient.invalidateQueries({ queryKey: ["secrets", id] });
    },
  });
}

export function useDeleteSecret() {
  const { token } = useAuthStore();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (id: string) => deleteSecret(token ?? undefined, id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["secrets"] });
    },
  });
}

export function useRotateSecret() {
  const { token } = useAuthStore();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, reason }: { id: string; reason?: string }) =>
      rotateSecret(token ?? undefined, id, reason),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["secrets"] });
      queryClient.invalidateQueries({ queryKey: ["secrets", variables.id] });
    },
  });
}

export function useSecretUsage(id: string) {
  const { token, isAuthenticated } = useAuthStore();
  return useQuery({
    queryKey: ["secrets", id, "usage"],
    queryFn: () => getSecretUsage(token ?? undefined, id),
    enabled: isAuthenticated && !!id,
  });
}
