import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  createCredential,
  listCredentials,
} from "@/api/credentials";
import { useAuthStore } from "@/state/auth-store";
import type { CreateCredentialRequest } from "@/types/credentials";

export function useCredentials(limit = 20) {
  const { token, isAuthenticated } = useAuthStore();
  return useQuery({
    queryKey: ["credentials", limit],
    queryFn: () => listCredentials(token ?? undefined, limit),
    enabled: isAuthenticated,
  });
}


export function useCreateCredential() {
  const { token } = useAuthStore();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (data: CreateCredentialRequest) => createCredential(token ?? undefined, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["credentials"] });
    },
  });
}




