import { useParams, useNavigate } from "@tanstack/react-router";
import { useMemo } from "react";
import { mockReleases } from "@/data/releases-mock";
import { ReleaseDetailPage } from "@/components/releases/release-detail-page";

export function ReleaseDetailRoute() {
  const { releaseName } = useParams({ from: "/releases/$releaseName" });
  const navigate = useNavigate();

  const release = useMemo(
    () => mockReleases.find((r) => r.name === decodeURIComponent(releaseName)),
    [releaseName],
  );

  if (!release) {
    return (
      <div className="flex flex-col items-center justify-center gap-4 py-20 text-muted-foreground">
        <p className="text-lg font-medium">Release not found</p>
        <button
          type="button"
          onClick={() => navigate({ to: "/releases" })}
          className="text-sm underline hover:text-foreground"
        >
          Back to releases
        </button>
      </div>
    );
  }

  return <ReleaseDetailPage release={release} />;
}
