import { useCallback, useMemo, useState } from "react";
import { Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { useReleases } from "@/hooks/use-releases";
import type { Release, ReleaseFormData } from "@/types/release";
import { createColumns } from "./columns";
import { ReleaseDialog } from "./release-dialog";
import { ReleasesDataTable } from "./releases-data-table";
import {
  ReleasesTableToolbar,
  defaultFilterState,
  type FilterState,
} from "./releases-table-toolbar";

function matchRelease(release: Release, filter: FilterState): boolean {
  if (filter.search) {
    const q = filter.search.toLowerCase();
    const matched =
      release.name.toLowerCase().includes(q) ||
      `${release.id}`.includes(q) ||
      release.team.toLowerCase().includes(q) ||
      release.defaultEnv.toLowerCase().includes(q) ||
      release.status.toLowerCase().includes(q) ||
      release.scrumMaster.toLowerCase().includes(q);
    if (!matched) return false;
  }

  if (filter.environments.length > 0 && !filter.environments.includes(release.defaultEnv))
    return false;
  if (filter.statuses.length > 0 && !filter.statuses.includes(release.status)) return false;
  if (filter.teams.length > 0 && !filter.teams.includes(release.team)) return false;

  if (filter.stageDateFrom && release.stageDate && release.stageDate.slice(0, 10) < filter.stageDateFrom)
    return false;
  if (filter.stageDateTo && release.stageDate && release.stageDate.slice(0, 10) > filter.stageDateTo)
    return false;
  if (filter.prodDateFrom && release.estProdDate && release.estProdDate.slice(0, 10) < filter.prodDateFrom)
    return false;
  if (filter.prodDateTo && release.estProdDate && release.estProdDate.slice(0, 10) > filter.prodDateTo)
    return false;

  return true;
}

export function ReleasesPage() {
  const { data: allReleases } = useReleases();
  const [tab, setTab] = useState("active");
  const [filter, setFilter] = useState<FilterState>(defaultFilterState);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingRelease, setEditingRelease] = useState<Release | undefined>(undefined);

  const activeReleases = useMemo(
    () => allReleases.filter((r) => r.status !== "archived"),
    [allReleases],
  );
  const archivedReleases = useMemo(
    () => allReleases.filter((r) => r.status === "archived"),
    [allReleases],
  );

  const sourceData = tab === "active" ? activeReleases : archivedReleases;

  const filteredData = useMemo(
    () => sourceData.filter((r) => matchRelease(r, filter)),
    [sourceData, filter],
  );

  const handleCreateRelease = useCallback(() => {
    setEditingRelease(undefined);
    setDialogOpen(true);
  }, []);

  const handleEdit = useCallback((release: Release) => {
    setEditingRelease(release);
    setDialogOpen(true);
  }, []);

  const handleSave = useCallback((_data: ReleaseFormData) => {
    setDialogOpen(false);
    setEditingRelease(undefined);
  }, []);

  const columns = useMemo(() => createColumns(handleEdit), [handleEdit]);

  return (
    <div className="flex flex-col gap-6 p-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">Releases</h1>
          <p className="mt-1 text-sm text-muted-foreground">
            Manage software releases across environments
          </p>
        </div>
        <Button onClick={handleCreateRelease}>
          <Plus className="mr-1.5 size-4" />
          Create release
        </Button>
      </div>

      <Tabs value={tab} onValueChange={(v) => { setTab(v); setIsDrawerOpen(false); }}>
        <div className="flex flex-col gap-2">
          <div className="flex items-center justify-between gap-4">
            <TabsList>
              <TabsTrigger value="active" className="gap-1.5">
                Active
                <Badge variant="secondary" className="rounded-full px-1.5 text-[11px] font-normal tabular-nums">
                  {activeReleases.length}
                </Badge>
              </TabsTrigger>
              <TabsTrigger value="archived" className="gap-1.5">
                Archived
                <Badge variant="secondary" className="rounded-full px-1.5 text-[11px] font-normal tabular-nums">
                  {archivedReleases.length}
                </Badge>
              </TabsTrigger>
            </TabsList>
            <ReleasesTableToolbar
              filter={filter}
              onFilterChange={setFilter}
              data={sourceData}
              isDrawerOpen={isDrawerOpen}
              onToggleDrawer={() => setIsDrawerOpen((v) => !v)}
              hideDrawer
            />
          </div>
          {isDrawerOpen && (
            <ReleasesTableToolbar
              filter={filter}
              onFilterChange={setFilter}
              data={sourceData}
              isDrawerOpen={isDrawerOpen}
              onToggleDrawer={() => setIsDrawerOpen((v) => !v)}
              drawerOnly
            />
          )}
        </div>
        <TabsContent value={tab} className="mt-4 space-y-4">
          <ReleasesDataTable columns={columns} data={filteredData} />
        </TabsContent>
      </Tabs>

      <ReleaseDialog
        key={editingRelease?.id ?? "create"}
        open={dialogOpen}
        onOpenChange={(open) => {
          setDialogOpen(open);
          if (!open) setEditingRelease(undefined);
        }}
        release={editingRelease}
        onSave={handleSave}
      />
    </div>
  );
}
